WITH ProductsBySupplier AS (SELECT supplier_id, MAX(launch_date) AS latest_launch_date, ROUND((100 * SUM(CASE WHEN brand = 'Umbrella' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_umbrella FROM products WHERE YEAR(launch_date) = 2024 GROUP BY supplier_id) SELECT s.id, s.city, s.supplier_name, P.latest_launch_date, P.pct_umbrella FROM suppliers s LEFT OUTER JOIN ProductsBySupplier P ON s.id = P.supplier_id
